import{_ as i,o as n,c as u,a2 as k}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Mpango wa Kichunguzi cha Njia Nyingine cha Kioo cha Nakala","description":"","frontmatter":{},"headers":[],"relativePath":"sw/85-复制镜异地考古方案.md","filePath":"sw/85-复制镜异地考古方案.md","lastUpdated":null}'),e={name:"sw/85-复制镜异地考古方案.md"};function t(h,a,o,w,l,s){return n(),u("div",null,[...a[0]||(a[0]=[k('<h1 id="mpango-wa-kichunguzi-cha-njia-nyingine-cha-kioo-cha-nakala" tabindex="-1">Mpango wa Kichunguzi cha Njia Nyingine cha Kioo cha Nakala <a class="header-anchor" href="#mpango-wa-kichunguzi-cha-njia-nyingine-cha-kioo-cha-nakala" aria-label="Permalink to &quot;Mpango wa Kichunguzi cha Njia Nyingine cha Kioo cha Nakala&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>85</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kioo cha nakala, kichunguzi cha njia nyingine, skana ya nafasi, ujenzi wa nakala, mawasiliano ya sifuri</td></tr></tbody></table><h2 id="_1-muhtasari-wa-mpango" tabindex="-1">1. Muhtasari wa Mpango <a class="header-anchor" href="#_1-muhtasari-wa-mpango" aria-label="Permalink to &quot;1. Muhtasari wa Mpango&quot;">​</a></h2><p>Mpango wa kichunguzi cha njia nyingine cha kioo cha nakala ni mpango wa kiutamadun wa kawaida wa kichunguzi cha kati ya ndege na kurudi nyuma kwa wakati wa Hengyuanzhou, wazo lake kuu ni &quot;usingie, usiguse, nakili tu&quot;. Kichunguzi cha jadi kinahitaji wafanyakazi wa kichunguzi kuingia wenyewe kwenye eneo la kichunguzi kufanya uchimbaji, ambacho hakikisha husababisha kuingilia kazi kwa kimwili na uchafuzi wa mazingira kwenye eneo. Mpango wa kioo cha nakala kupitia teknolojia ya sheria za nafasi, katika hali ya kutogusa kabisa kipengele cha asili, kunakili kamile lengo la kichunguzi kwenye nafasi iliyotengwa ya njia nyingine, kisha kufanya operesheni zote za kichunguzi ndani ya nafasi iliyotengwa.</p><p>&quot;Njia nyingine&quot; ni sifa kuu ya mpango huu. Operesheni ya nakala inakamilishwa katika eneo salama linalokaribia ndege ya lengwa au kipindi cha lengwa, lakini uzalishaji wa nakala na utafiti wa kichunguzi unaofuata unafanyika kabisa katika nafasi ya kujitegemea iliyotengwa kabisa na lengo. Hii inamaanisha kuwa wafanyakazi wa kichunguzi hawahitaji kuingia kwenye eneo la lengwa tangu mwanzo hadi mwisho, hata hawahitaji kuingia kwenye ndege ya lengwa — mchakato wote wa kichunguzi unaweza kukamilishwa kwa umbali katika nafasi iliyotengwa ya ndege ya mwenyewe.</p><p>Msingi wa kiufundi wa mpango wa kichunguzi cha njia nyingine cha kioo cha nakala ni matumizi ya juu ya mfumo wa usimamizi wa sheria za nafasi. Watu tu waliofikia hatua ya nne (Ufalme wa Haki ya Utu) au zaidi ya mfumo wa usimamizi wa sheria za nafasi, au vyombo vya kioo cha nakala vilivyovamiwa na kiwango sawa cha kiufundi, ndivyo wenyeweza kufanya operesheni ya nakala ya usahihi wa juu. Kwa sasa Hengyuanzhou imefikisha uzalishaji wa wingi wa uhandisi wa kioo cha nakala, kifaa cha kioo cha nakala cha aina ya kawaida kinaweza kuendeshwa na mtu aliyeefikia hatua ya tatu (Ufalme wa Mabadiliko ya Utu) kukamilisha kazi za kawaida za kichunguzi.</p><h2 id="_2-kanuni-ya-kiufundi-ya-kioo-cha-nakala" tabindex="-1">2. Kanuni ya Kiufundi ya Kioo cha Nakala <a class="header-anchor" href="#_2-kanuni-ya-kiufundi-ya-kioo-cha-nakala" aria-label="Permalink to &quot;2. Kanuni ya Kiufundi ya Kioo cha Nakala&quot;">​</a></h2><p>Vipengele vya msingi vya kioo cha nakala ni &quot;safu ya skana ya sheria za nafasi&quot; na &quot;kijenzi cha ujenzi wa hali ya chembe&quot;. Mchakato wake wa kazi umegawanywa katika hatua tatu:</p><h3 id="_2-1-hatua-ya-skana-ya-nafasi" tabindex="-1">2.1 Hatua ya Skana ya Nafasi <a class="header-anchor" href="#_2-1-hatua-ya-skana-ya-nafasi" aria-label="Permalink to &quot;2.1 Hatua ya Skana ya Nafasi&quot;">​</a></h3><p>Baada ya kukamilishwa kwa utepelezaji wa kioo cha nakala, kwanza kufanya skana ya sheria za nafasi ya kila upande kwenye eneo la lengwa. Safu ya skana inatoa mawimbi ya nafasi ya masafa ya juu, yanayopenya miundo yote ya vifaa na nishati ndani ya eneo la lengwa, na kurekodi parameta zote za quantum za kila chembe kama vile nafasi, mwendo, mzunguko, hali ya nishati. Wakati huo huo, safu ya skana pia inagundua usambazaji wa uwanja wa nishati, mabadiliko ya parameta za sheria, na mabaki ya alama za fahari ndani ya eneo la lengwa.</p><p>Mchakato wa skana ni wa kuzingatia kabisa — mawimbi ya nafasi hayabadilishi hali yoyote ya vifaa wanayopitia, kwa hivyo hawasababishi kuingilia kazi yoyote kwenye eneo la kichunguzi. Usahihi wa skana unategemea kiwango cha kiufundi cha kioo cha nakala, usahihi wa skana wa kifaa cha aina ya kawaida ni kiwango cha chini ya atomu, kifaa cha aina ya utafiti cha juu kinaweza kufikia kiwango cha kwak.</p><h3 id="_2-2-hatua-ya-usafirishaji-wa-data" tabindex="-1">2.2 Hatua ya Usafirishaji wa Data <a class="header-anchor" href="#_2-2-hatua-ya-usafirishaji-wa-data" aria-label="Permalink to &quot;2.2 Hatua ya Usafirishaji wa Data&quot;">​</a></h3><p>Data kubwa inayopatikana kutoka kwa skana inasafirishwa hadi kwenye nafasi iliyotengwa kupitia njia ya usimbaji wa mtandao wa nanga. Usafirishaji wa data unatumia &quot;itifaki ya usimbaji wa hali ya quantum&quot;, na kuhakikisha kuwa data haibiwi au kubadilishwa wakati wa usafirishaji. Kiasi cha data ni kikubwa sana — kwa eneo la saizi ya chumba cha kawaida, kiasi cha data kamili ya skana ni takriban 10 kwa nguvu 30 baiti, na kinahitaji njia ya data ya mwelekeo wa juu wa mtandao wa nanga kukamilisha usafirishaji katika muda wa busara.</p><h3 id="_2-3-hatua-ya-ujenzi-wa-nakala" tabindex="-1">2.3 Hatua ya Ujenzi wa Nakala <a class="header-anchor" href="#_2-3-hatua-ya-ujenzi-wa-nakala" aria-label="Permalink to &quot;2.3 Hatua ya Ujenzi wa Nakala&quot;">​</a></h3><p>Baada ya kijenzi cha ujenzi wa hali ya chembe ndani ya nafasi iliyotengwa kupokea data, kulingana na parameta sahihi zilizorekodiwa katika skana, kinajenga tena nakala kamili ya eneo la lengwa chembe kwa chembe ndani ya nafasi iliyotengwa. Mchakato wa ujenzi unaanza kutoka kwa chembe za safu ya chini, na kujenga safu kwa safu hadi juu atomu, molekuli, miundo ya vifaa, uwanja wa nishati, na alama za fahari. Baada ya kukamilishwa kwa ujenzi, nakala na kipengele cha asili ni sawa kabisa katika kiwango cha kimwili — ikiwa ni pamoja na vifaa vya kichunguzi, miundo, alama za uso, uharibifu wa ndani, hata uwanja wa nishati uliobaki na alama za fahari.</p><p>Inahitajika kuelezea mahsusi kwamba &quot;alama za fahari&quot; ndani ya nakala ni mabaki ya fahari ya mazingira ambayo kipengele cha asili kimezimeza wakati wa kuwepo kwa muda mrefu, sio mwili wa kweli wa fahari. Nakala haina fahari ya kujitegemea, na haitazalisha shughuli yoyote mpya ya fahari. Jambo hili limethibitishwa kupitia tafsiri ya kisheria ya Korti ya Symbiosis, nakala haiiangi katika kategoria ya &quot;maisha&quot;, na utafiti wa nakala huhusiani na maswala ya maadili ya maisha.</p><h2 id="_3-uainishaji-wa-kioo-cha-nakala-na-mazingira-yanayofaa" tabindex="-1">3. Uainishaji wa Kioo cha Nakala na Mazingira Yanayofaa <a class="header-anchor" href="#_3-uainishaji-wa-kioo-cha-nakala-na-mazingira-yanayofaa" aria-label="Permalink to &quot;3. Uainishaji wa Kioo cha Nakala na Mazingira Yanayofaa&quot;">​</a></h2><p>Kulingana na upeo wa nakala, usahihi, na kazi, kioo cha nakala kimegawanywa katika aina nne zifuatazo:</p><table tabindex="0"><thead><tr><th>Kioo</th><th>Upeo wa Nakala</th><th>Kiwango cha Usahihi</th><th>Mazingira Yanayofaa</th><th>Hitaji la Utu wa Operesheni</th></tr></thead><tbody><tr><td>Aina ya Kawaida (CM-S)</td><td>Zaidi ya 100 mita za ujazo</td><td>Chini ya atomu</td><td>Kichunguzi cha kawaida cha kipengele kimoja cha kichunguzi, mabaki madogo</td><td>Ufalme wa Mabadiliko ya Utu (hatua ya tatu)</td></tr><tr><td>Aina ya Upanuzi (CM-E)</td><td>Zaidi ya 10000 mita za ujazo</td><td>Chini ya atomu</td><td>Nakala kamili ya majengo makubwa, mabaki ya kiwango cha kijiji</td><td>Ufalme wa Haki ya Utu (hatua ya nne)</td></tr><tr><td>Aina ya Utafiti (CM-R)</td><td>Zaidi ya 1000 mita za ujazo</td><td>Kwak</td><td>Utafiti wa vifaa vya kichunguzi vya thamani vinavyohitaji uchambuzi wa usahihi wa juu sana</td><td>Ufalme wa Haki ya Utu (hatua ya nne)+ hatua ya tatu ya mfumo wa ukurikizi wa tokea</td></tr><tr><td>Aina ya Maalum (CM-X)</td><td>Zaidi ya 1 kilomita ya ujazo</td><td>Chini ya atomu</td><td>Nakala kamili ya uokoaji wa vikundi vya mabaki ya kiwango cha mji</td><td>Ufalme wa Asili ya Utu (hatua ya tano) au msaada wa chombo</td></tr></tbody></table><p>Kwa mazingira maalum kama vile ndege zenye sheria zilizovunjika, inahitajika kutumia &quot;kioo cha nakala cha aina ya kulingana na sheria&quot; kilirekebishwa kwa kiwango cha maalum, na safu yake ya skana inaweza kulingana na mazingira yasiyo thabiti ya sheria, na kuhakikisha kuwa data sahihi za skali bado zinapatikana katikati ya mabadiliko ya sheria.</p><h2 id="_4-mambo-muhimu-ya-operesheni-ya-kichunguzi-cha-njia-nyingine" tabindex="-1">4. Mambo Muhimu ya Operesheni ya Kichunguzi cha Njia Nyingine <a class="header-anchor" href="#_4-mambo-muhimu-ya-operesheni-ya-kichunguzi-cha-njia-nyingine" aria-label="Permalink to &quot;4. Mambo Muhimu ya Operesheni ya Kichunguzi cha Njia Nyingine&quot;">​</a></h2><p>Mpango wa kichunguzi cha njia nyingine cha kioo cha nakala katika operesheni ya vitendo unahitaji kuzingatia mambo muhimu yafuatayo:</p><ol><li><p><strong>Uteuzi wa Nafasi ya Utepelezaji</strong>: Kioo cha nakala kinapaswa kuwekwa nje ya umbali wa usalama wa sheria wa eneo la lengwa, ambacho hakikisha kuwa upeo wa skana unafunika lengo, na pia kuepuka kifaa chenyewe kusababisha usumbufu wa sheria kwenye eneo la lengwa. Umbali wa usalama kwa kawaida ni zaidi ya mara 3 ya ukubwa wa juu wa eneo la lengwa.</p></li><li><p><strong>Uteuzi wa Wakati wa Nakala</strong>: Kwa kichunguzi cha kurudi nyuma kwa wakati, utepelezaji na skana ya kioo cha nakala vinapaswa kufanyika katika &quot;kipindi cha utulivu wa sheria&quot; cha kipindi cha lengwa, na kuepuka kufanya operesheni ya nakala wakati wa tukio la kihistoria linalotokea — wakati huu msongamano wa mnyororo wa sababu ni wa juu sana, na matumizi ya nishati ya operesheni ya nakala yataongezeka kwa kiwango kikubwa, na yanaweza kusababisha usumbufu dhaifu kwenye mstari wa sababu.</p></li><li><p><strong>Uthibitisho wa Ukamilifu wa Nakala</strong>: Baada ya kukamilishwa kwa ujenzi wa nakala, lazima kufanyike &quot;uthibitisho wa usawaziko wa nakala-kipengele cha asili&quot;. Njia ya kuthibitisha ni kufanya skana ya pili kwenye nakala, kulinganisha data za skana na data za skana za asili chembe kwa chembe, na kiwango cha makosa lazima kiwe chini ya 10 kwa nguvu ya hasi 12. Ikiwa kiwango cha makosa kimezidi kiwango, lazima nakala iharibike na kunakiliwa tena.</p></li><li><p><strong>Mkakati wa Nakala ya Mzunguko Mingi</strong>: Kwa mabaki makubwa sana, nakala ya mara moja inaweza isifunike eneo lote. Wakati huu inatumika mkakati wa &quot;nakala ya mzunguko mingi kulingana na eneo&quot;, inayogawa mabaki katika maeneo mbalimbali kunakiliwa kila moja, kisha kufanya kuunganisha ndani ya nafasi iliyotengwa. Wakati wa kuunganisha, inahitajika kuhakikisha kuwa hali za chembe katika mipaka ya maeneo yanayofuatana zinunganishwa bila pengo, na hakuna kutokea kwa kizuizi cha sheria.</p></li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Mpango wa kichunguzi cha njia nyingine cha kioo cha nakala ni mfano wa matumizi ya uhandisi wa sheria za nafasi ya Hengyuanzhou. Kupitia njia ya kiufundi ya &quot;nakala ya mawasiliano ya sifuri, utafiti wa njia nyingine&quot;, inasuluhisha kimsingi mgogoro kati ya &quot;upatikanaji wa maarifa&quot; na &quot;ulinzi wa eneo&quot; katika kichunguzi cha jadi. Mpango huu haukuongeza ufanisi wa kichunguzi kwa kiwango kikubwa tu, bali muhimu zaidi, inahakikisha kuwa kila kichunguzi hakiachi alama yoyote kwenye ustaarabu wa lengwa na eneo la kihistoria — kwa kweli inatimiza &quot;nimeondoka kwa upole, kama vile nilivyojaa kwa upole&quot;.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>84-Muhtasari wa Itifaki ya Kichunguzi</li><li>86-Mchakato wa Uchafuzi wa Chini katika Nafasi Iliyotengwa</li><li>63-Kanuni ya Kiufundi ya Kioo cha Nakala</li></ul>',27)])])}const d=i(e,[["render",t]]);export{m as __pageData,d as default};
